import ExcelJS from "exceljs";
import type { Cell, Worksheet } from "exceljs";

// ---------------------------------------------------------------------------
// Workbook readers
//
// Export tests reopen the generated file and inspect real cells, so they assert
// what a Program Head would open: worksheet structure, printed values, numeric
// cell types, and the absence of anything the export must never carry.
// ---------------------------------------------------------------------------

export type CellValue = ExcelJS.CellValue;

/** Load a generated workbook buffer so tests read the real file. */
export async function loadWorkbook(bytes: Uint8Array): Promise<ExcelJS.Workbook> {
  const workbook = new ExcelJS.Workbook();
  // exceljs types its loader against its own Buffer build; the generated bytes
  // are the same shape.
  await workbook.xlsx.load(bytes as unknown as Parameters<typeof workbook.xlsx.load>[0]);
  return workbook;
}

/** Every printed value of a sheet, flattened, for "must not contain" scans. */
export function sheetText(worksheet: Worksheet): string {
  const values: string[] = [];
  worksheet.eachRow((row) => {
    row.eachCell((cell) => {
      if (typeof cell.value === "string") values.push(cell.value);
      else if (typeof cell.value === "number") values.push(String(cell.value));
    });
  });
  return values.join("\n");
}

/** Row number of the first row whose first cell equals `text`. */
export function findRow(worksheet: Worksheet, text: string): number {
  let found = 0;
  worksheet.eachRow((row, rowNumber) => {
    if (found === 0 && row.getCell(1).value === text) found = rowNumber;
  });
  return found;
}

/** Row number of the first row matching every given column value. */
export function findRowByValues(
  worksheet: Worksheet,
  matcher: Record<number, string | number>
): number {
  let found = 0;
  worksheet.eachRow((row, rowNumber) => {
    if (found > 0) return;
    const matches = Object.entries(matcher).every(([column, expected]) => {
      const cell = row.getCell(Number(column));
      return cellValue(cell) === expected || String(cellValue(cell) ?? "") === String(expected);
    });
    if (matches) found = rowNumber;
  });
  return found;
}

/** Plain value of a cell: numbers stay numbers, everything else becomes text. */
export function cellValue(cell: Cell): string | number | boolean | Date | null {
  const value = cell.value;
  if (value === null || value === undefined) return null;
  if (typeof value === "object" && "result" in value) {
    return (value.result ?? null) as string | number | boolean | Date | null;
  }
  if (typeof value === "object" && "richText" in value) {
    return value.richText.map((part) => part.text).join("");
  }
  if (value instanceof Date) return value;
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return value;
  }
  return null;
}

/** Numeric value of a cell, or null when the cell holds no number. */
export function numericCell(cell: Cell): number | null {
  const value = cellValue(cell);
  return typeof value === "number" ? value : null;
}

/**
 * Contiguous data rows after a header row. A row belongs to the table while its
 * first column still holds a data value; a blank cell or the next section
 * heading ends the table, so stacked class-group blocks never merge.
 */
export function dataRowsAfter(worksheet: Worksheet, headerRow: number): number[] {
  const rows: number[] = [];
  let rowNumber = headerRow + 1;
  for (;;) {
    const cell = worksheet.getCell(rowNumber, 1);
    const first = cell.value;
    if (first === null || first === undefined || String(first).trim().length === 0) break;
    if (isSectionHeading(cell)) break;
    rows.push(rowNumber);
    rowNumber += 1;
  }
  return rows;
}

/** Section headings are the only bold 12pt cells the builders write in column 1. */
function isSectionHeading(cell: Cell): boolean {
  return cell.font?.bold === true && (cell.font?.size ?? 0) >= 12;
}

/** The single data row whose given column equals `value`. */
export function dataRowWith(
  worksheet: Worksheet,
  headerRow: number,
  column: number,
  value: string | number
): number {
  const rows = dataRowsAfter(worksheet, headerRow);
  const match = rows.find((row) => {
    const cellValueAtRow = cellValue(worksheet.getCell(row, column));
    return cellValueAtRow === value || String(cellValueAtRow ?? "") === String(value);
  });
  if (!match) {
    throw new Error(
      `No data row with column ${column} = ${String(value)}. Rows: ${JSON.stringify(
        rows.map((row) => [row, cellValue(worksheet.getCell(row, column))])
      )}`
    );
  }
  return match;
}

/** Ordered values of one row. */
export function rowValues(worksheet: Worksheet, row: number, columnCount: number): CellValue[] {
  return Array.from({ length: columnCount }, (_, index) =>
    cellValue(worksheet.getCell(row, index + 1))
  );
}
